/**
 * JavaScript to ES Module (.mjs) Converter
 * 
 * Converts .js files to .mjs by:
 * 1. Changing module.exports to export statements
 * 2. Adding ES module header comment
 * 3. Preserving all functionality
 * 
 * Usage: node scripts/js-to-mjs-converter.js
 */

const fs = require('fs');
const path = require('path');

/**
 * Convert JavaScript content to ES Module format
 */
function convertJsToMjs(content) {
  const mjsHeader = `/**
 * ========================================
 * ES MODULE VERSION (AUTO-GENERATED)
 * ========================================
 * 
 * DO NOT EDIT THIS FILE DIRECTLY!
 * 
 * This .mjs file is auto-generated from the .js gold standard.
 * To make changes, edit: supabase/functions/_shared/CharacterConsistencyService.js
 * Then run: node scripts/js-to-mjs-converter.js
 * 
 * Purpose: ES module version for vendor bundle compatibility
 * Generated: ${new Date().toISOString()}
 */

`;

  // Convert module.exports to export
  let mjsContent = content
    .replace(/module\.exports\s*=\s*{([^}]+)}/g, 'export { $1 }')
    .replace(/module\.exports\s*=\s*/g, 'export default ')
    .replace(/module\.exports\./g, 'export const ');
  
  return mjsHeader + mjsContent;
}

/**
 * Main conversion function
 */
async function main() {
  try {
    // Input: Gold standard .js file
    const inputPath = path.join(__dirname, '../supabase/functions/_shared/CharacterConsistencyService.js');
    
    // Output: ES module .mjs file
    const outputPath = path.join(__dirname, '../supabase/functions/_vendor/CharacterConsistencyService.mjs');
    
    console.log('🔄 Starting .js → .mjs conversion...');
    console.log(`📥 Input:  ${inputPath}`);
    console.log(`📤 Output: ${outputPath}`);
    
    // Read gold standard file
    if (!fs.existsSync(inputPath)) {
      throw new Error(`Input file not found: ${inputPath}`);
    }
    
    const jsContent = fs.readFileSync(inputPath, 'utf8');
    console.log(`✅ Read ${jsContent.length} characters from input file`);
    
    // Convert to .mjs
    const mjsContent = convertJsToMjs(jsContent);
    
    // Ensure output directory exists
    const outputDir = path.dirname(outputPath);
    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
      console.log(`📁 Created output directory: ${outputDir}`);
    }
    
    // Write output file
    fs.writeFileSync(outputPath, mjsContent, 'utf8');
    console.log(`✅ Wrote ${mjsContent.length} characters to output file`);
    
    console.log('');
    console.log('🎉 Conversion complete!');
    console.log('');
    console.log('Summary:');
    console.log(`  - Input lines:  ${jsContent.split('\n').length}`);
    console.log(`  - Output lines: ${mjsContent.split('\n').length}`);
    console.log(`  - Size change:  ${mjsContent.length - jsContent.length} bytes (header added)`);
    
  } catch (error) {
    console.error('❌ Conversion failed:', error.message);
    console.error(error.stack);
    process.exit(1);
  }
}

// Run if called directly
if (require.main === module) {
  main().catch(console.error);
}

module.exports = { convertJsToMjs };
